let db=loadDb(), activeAdminTab='criteria', schoolPreview=[], studentPreview=[];

function freshDb(){return{version:2,criteria:[],students:[],results:[],runs:[],audit:[],scoreConversion:{version:1,bands:[[90,5],[80,4],[70,3],[60,2],[0,1]]},teacherPin:'6673'}}
function safeRead(key,fallback){try{const raw=localStorage.getItem(key);return raw===null?fallback:JSON.parse(raw)}catch(error){console.error(`${key} JSON 손상`,error);return fallback}}
function criteriaIdentity(c){return`${String(c?.schoolName||'').trim()}|${String(c?.department||'전체').trim()}|${Number(c?.year)||2027}`}
function criteriaFreshness(c){const time=Date.parse(c?.updatedAt||'')||0;return[time,Number(c?.version)||0]}
function isCriteriaNewer(candidate,current){const a=criteriaFreshness(candidate),b=criteriaFreshness(current);return a[0]>b[0]||(a[0]===b[0]&&a[1]>b[1])}
function mergeCriteriaSources(...sources){
  const merged=[],byId=new Map(),byKey=new Map();
  sources.flat().filter(Boolean).forEach(c=>{
    const id=String(c.id||''),key=criteriaIdentity(c),found=(id&&byId.get(id))||byKey.get(key);
    if(found!==undefined){if(isCriteriaNewer(c,merged[found]))merged[found]=c;return}
    const index=merged.push(c)-1;if(id)byId.set(id,index);byKey.set(key,index)
  });
  return merged
}
function recoverLegacyCriteria(existing=[]){const knownSchools=new Set(existing.map(c=>String(c.schoolName||'').trim()).filter(Boolean)),legacy=safeRead('odong-admission-project-v1',[]);return(Array.isArray(legacy)?legacy:[]).filter(s=>s?.name&&!knownSchools.has(String(s.name).trim())).map((s,i)=>{const c=defaultCriteria(existing.length+i+1);c.schoolName=String(s.name).trim();c.department=String(s.departments||'전체').trim()||'전체';c.status='적용';c.expected=Number(s.cutoff)||0;c.safe=Math.max(c.expected,Math.min(c.schoolTotal,c.expected+10));c.source=s.url||'';c.memo=s.memo||'';c.version=1;return c})}
function loadDb(){
  const next=freshDb();
  const hasV2=Object.values(STORAGE_KEYS).some(key=>localStorage.getItem(key)!==null);
  if(hasV2){const current=safeRead(STORAGE_KEYS.schools,[]),backup=safeRead(SCHOOL_BACKUP_KEY,[]),old=safeRead(DB_KEY,null);next.criteria=mergeCriteriaSources(current,backup,Array.isArray(old?.criteria)?old.criteria:[]);next.criteria=mergeCriteriaSources(next.criteria,recoverLegacyCriteria(next.criteria));next.students=safeRead(STORAGE_KEYS.students,Array.isArray(old?.students)?old.students:[]);next.results=safeRead(STORAGE_KEYS.results,Array.isArray(old?.results)?old.results:[]);next.runs=safeRead(STORAGE_KEYS.runs,Array.isArray(old?.runs)?old.runs:[]);next.audit=safeRead(STORAGE_KEYS.audit,Array.isArray(old?.audit)?old.audit:[]);Object.assign(next,safeRead(STORAGE_KEYS.config,{}));next.teacherPin=String(next.teacherPin||'6673');if(next.criteria.length>current.length){try{if(current.length)localStorage.setItem(SCHOOL_BACKUP_KEY,JSON.stringify(current));localStorage.setItem(STORAGE_KEYS.schools,JSON.stringify(next.criteria));next.audit.unshift({at:new Date().toISOString(),action:`학교자료 자동 복구 ${next.criteria.length-current.length}건`})}catch(error){console.error('학교자료 자동 복구 저장 실패',error)}}return next}
  const old=safeRead(DB_KEY,null);if(old)Object.assign(next,old);next.teacherPin=String(next.teacherPin||'6673');
  return migrateLegacyStorage(next);
}
function writeSeparatedStorage(){
  const backups=Object.fromEntries(Object.values(STORAGE_KEYS).map(k=>[k,localStorage.getItem(k)]));
  try{if(backups[STORAGE_KEYS.schools])localStorage.setItem(SCHOOL_BACKUP_KEY,backups[STORAGE_KEYS.schools]);localStorage.setItem(STORAGE_KEYS.schools,JSON.stringify(db.criteria));localStorage.setItem(STORAGE_KEYS.students,JSON.stringify(db.students));localStorage.setItem(STORAGE_KEYS.results,JSON.stringify(db.results));localStorage.setItem(STORAGE_KEYS.runs,JSON.stringify(db.runs));localStorage.setItem(STORAGE_KEYS.audit,JSON.stringify(db.audit));localStorage.setItem(STORAGE_KEYS.config,JSON.stringify({version:db.version,scoreConversion:db.scoreConversion,teacherPin:db.teacherPin}));}
  catch(error){Object.entries(backups).forEach(([k,v])=>v===null?localStorage.removeItem(k):localStorage.setItem(k,v));throw new Error(error?.name==='QuotaExceededError'?'저장공간이 부족합니다. 기존 자료는 보존했습니다.':'자료 저장에 실패했습니다. 기존 자료는 보존했습니다.')}
}
function saveDb(action='저장',preserveSchools=true){if(preserveSchools)db.criteria=mergeCriteriaSources(safeRead(STORAGE_KEYS.schools,[]),db.criteria);db.audit.unshift({at:new Date().toISOString(),action});writeSeparatedStorage()}
function migrateLegacyStorage(target=freshDb()){
  try{
    const legacySchools=safeRead('odong-admission-project-v1',[]);
    if(Array.isArray(legacySchools)&&legacySchools.length&&!target.criteria.length){target.criteria=legacySchools.map((s,i)=>{const c=defaultCriteria(i+1);c.schoolName=s.name||'';c.department=s.departments||'전체학과';c.status='적용 가능';c.expected=Number(s.cutoff)||0;c.safe=Math.min(100,c.expected+10);c.source=s.url||'';c.memo=s.memo||'';c.version=1;return c});target.audit.unshift({at:new Date().toISOString(),action:`기존 학교자료 ${target.criteria.length}건 마이그레이션`})}
    writeMigrated(target);return target;
  }catch(error){console.error('기존자료 마이그레이션 실패',error);return target}
  function writeMigrated(data){try{localStorage.setItem(STORAGE_KEYS.schools,JSON.stringify(data.criteria));localStorage.setItem(STORAGE_KEYS.students,JSON.stringify(data.students));localStorage.setItem(STORAGE_KEYS.results,JSON.stringify(data.results));localStorage.setItem(STORAGE_KEYS.runs,JSON.stringify(data.runs));localStorage.setItem(STORAGE_KEYS.audit,JSON.stringify(data.audit));localStorage.setItem(STORAGE_KEYS.config,JSON.stringify({version:data.version,scoreConversion:data.scoreConversion,teacherPin:data.teacherPin}))}catch(error){console.error('마이그레이션 저장 실패: 기존 키는 삭제하지 않습니다.',error)}}
}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d}
function bool(v){if(typeof v==='boolean')return v;const s=String(v??'').trim().toUpperCase();if(['Y','예','TRUE','1'].includes(s))return true;if(['N','아니오','FALSE','0',''].includes(s))return false;throw new Error(`반영 여부 값 오류: ${v}`)}
function uid(prefix){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function notify(msg,type='ok'){const el=document.getElementById('notice');el.className=`mb-4 rounded-xl p-3 text-sm ${type==='error'?'bg-red-50 text-red-700':'bg-emerald-50 text-emerald-700'}`;el.textContent=msg;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),5000)}

function validateScoreConversionRules(rules=db.scoreConversion){if(!rules?.bands?.length)return{ok:false,error:'변환 기준이 없습니다.'};return{ok:true}}
function convertRawScoreToGrade(raw){const x=n(raw,NaN);if(!Number.isFinite(x)||x<0||x>100)throw new Error('원점수는 0~100이어야 합니다.');return x>=90?5:x>=80?4:x>=70?3:x>=60?2:1}

function tokenizeFormula(input){
  const s=String(input||'').replaceAll('×','*').replaceAll('÷','/').trim();if(!s)throw new Error('산출식이 비어 있습니다.');
  if(/[;{}\[\]'".`]|(?:eval|function|window|document)/i.test(s))throw new Error('허용되지 않은 기호가 포함되어 있습니다.');
  const out=[];let i=0;
  while(i<s.length){if(/\s/.test(s[i])){i++;continue}if(/[+\-*/()]/.test(s[i])){out.push(s[i++]);continue}
    const nm=s.slice(i).match(/^\d+(?:\.\d+)?/);if(nm){out.push(Number(nm[0]));i+=nm[0].length;continue}
    const vm=FORMULA_VARS.find(v=>s.startsWith(v,i));if(vm){out.push(vm);i+=vm.length;continue}throw new Error('등록되지 않은 변수입니다.');}
  return out;
}
function safelyEvaluateFormula(formula,vars={}){
  const t=tokenizeFormula(formula);let p=0;
  function primary(){const x=t[p++];if(x==='('){const v=expr();if(t[p++]!==')')throw new Error('괄호가 맞지 않습니다.');return v}if(x==='-')return-primary();if(typeof x==='number')return x;if(FORMULA_VARS.includes(x))return n(vars[x]);throw new Error('괄호가 맞지 않습니다.')}
  function term(){let v=primary();while(t[p]==='*'||t[p]==='/'){const op=t[p++],r=primary();if(op==='/'&&r===0)throw new Error('0으로 나눌 수 없습니다.');v=op==='*'?v*r:v/r}return v}
  function expr(){let v=term();while(t[p]==='+'||t[p]==='-'){const op=t[p++],r=term();v=op==='+'?v+r:v-r}return v}
  const result=expr();if(p!==t.length)throw new Error('괄호가 맞지 않습니다.');if(!Number.isFinite(result))throw new Error('계산 결과가 숫자가 아닙니다.');return result
}
function defaultCriteria(sequence=null){const next=sequence??(db.criteria.reduce((m,c)=>Math.max(m,Number(String(c.id||'').split('-').pop())||0),0)+1);const id=`SC-2027-${String(next).padStart(4,'0')}`;return{id,schoolName:'',department:'',year:2027,status:'적용',schoolTotal:100,academicMax:70,academicWeight:1,useAcademicFormula:false,academicFormula:'(평점합 ÷ 40) × 50',expected:70,safe:80,challengeGap:5,rounding:'소수 둘째 자리 반올림',source:'',memo:'',version:1,semesters:Object.fromEntries(SEMESTERS.map(x=>[x,{enabled:true,weight:1}])),subjects:Object.fromEntries(SUBJECTS.map(x=>[x,{enabled:true,weight:1}])),nonAcademic:Object.fromEntries(NON_ACADEMIC.map(x=>[x,{enabled:false,inputMax:20,schoolMax:0,weight:1,method:'자동 비율 환산',formula:'',deductionPerDay:1,fullHours:30}]))}}
function validateSchoolCriteriaRow(c){const errors=[],warnings=[];if(!c.schoolName)errors.push('학교명이 입력되지 않았습니다.');if(!c.department)errors.push('모집학과가 입력되지 않았습니다.');if(!c.year)errors.push('적용학년도가 누락되었습니다.');if(!CRITERIA_STATUS.includes(c.status))errors.push('적용상태 오류');if(n(c.schoolTotal)<=0)errors.push('학교 총점은 0보다 커야 합니다.');if(n(c.academicMax)<=0)errors.push('교과 반영 만점은 0보다 커야 합니다.');if(!Object.values(c.semesters||{}).some(x=>x.enabled))errors.push('반영할 학기가 한 개 이상 필요합니다.');if(!Object.values(c.subjects||{}).some(x=>x.enabled))errors.push('반영할 과목이 한 개 이상 필요합니다.');if(c.useAcademicFormula)try{safelyEvaluateFormula(c.academicFormula,Object.fromEntries(FORMULA_VARS.map(x=>[x,1])))}catch(e){errors.push('교과산출식: '+e.message)}if(n(c.expected)>n(c.schoolTotal))errors.push('예상합격점수는 학교 총점을 초과할 수 없습니다.');if(n(c.safe)>n(c.schoolTotal))errors.push('안정예상점수는 학교 총점을 초과할 수 없습니다.');if(n(c.safe)<n(c.expected))errors.push('안정예상점수는 예상합격점수보다 낮을 수 없습니다.');if(n(c.challengeGap)<0)errors.push('도전 허용 점수 차이는 0 이상이어야 합니다.');const maxSum=n(c.academicMax)+NON_ACADEMIC.reduce((a,k)=>a+(c.nonAcademic?.[k]?.enabled?n(c.nonAcademic[k].schoolMax):0),0);if(Math.abs(maxSum-n(c.schoolTotal))>.001)warnings.push(`반영 만점 합계(${maxSum})와 학교 총점(${c.schoolTotal})이 다릅니다.`);return{ok:!errors.length,errors,warnings}}

function workbookRows(wb,name){const ws=wb.Sheets[name];return ws?XLSX.utils.sheet_to_json(ws,{defval:''}):null}
function parseSchoolCriteriaExcel(wb){
  const base=workbookRows(wb,'학교산출기준');if(!base)throw new Error('필수 시트 누락: 학교산출기준');
  const sem=workbookRows(wb,'학기설정');const sub=workbookRows(wb,'과목설정');const non=workbookRows(wb,'비교과설정');if(!sem||!sub||!non)throw new Error('학기설정, 과목설정, 비교과설정 시트가 필요합니다.');
  return base.map((r,i)=>{const c=defaultCriteria();Object.assign(c,{id:String(r['기준ID']||c.id).trim(),schoolName:String(r['학교명']||'').trim(),department:String(r['모집학과']||'').trim(),year:n(r['적용학년도']),status:String(r['적용상태']||'작성 중').trim(),schoolTotal:n(r['학교총점']),academicMax:n(r['교과반영만점']),academicWeight:n(r['전체교과가중치'],1),academicFormula:String(r['교과산출식']||''),expected:n(r['예상합격점수']),safe:n(r['안정예상점수']),challengeGap:n(r['도전허용점수차이']),rounding:String(r['소수점처리방식']||'소수 둘째 자리 반올림'),source:String(r['자료출처']||''),memo:String(r['참고메모']||''),excelRow:i+2});
    const sr=sem.find(x=>String(x['기준ID'])===c.id)||{};SEMESTERS.forEach(x=>c.semesters[x]={enabled:bool(sr[`${x}_반영`]??'N'),weight:n(sr[`${x}_가중치`],1)});
    const ur=sub.find(x=>String(x['기준ID'])===c.id)||{};SUBJECTS.forEach(x=>c.subjects[x]={enabled:bool(ur[`${x}_반영`]??'N'),weight:n(ur[`${x}_가중치`],1)});
    const nr=non.find(x=>String(x['기준ID'])===c.id)||{};NON_ACADEMIC.forEach(k=>{const px=k==='면접'?'면접':k;c.nonAcademic[k]={enabled:bool(nr[`${px}_반영`]??'N'),inputMax:n(nr[`${px}_기본입력만점`],20),schoolMax:n(nr[`${px}_학교반영만점`]),weight:n(nr[`${px}_가중치`],1),method:String(nr[`${px}_계산방식`]||'자동 비율 환산'),formula:String(nr[`${px}_산출식`]||'')}});c.validation=validateSchoolCriteriaRow(c);return c})
}
function validateSchoolWorkbook(wb){try{const rows=parseSchoolCriteriaExcel(wb);const ids=new Set(),keys=new Set();for(const c of rows){if(ids.has(c.id))c.validation.errors.push('중복 기준ID');ids.add(c.id);const k=`${c.schoolName}|${c.department}|${c.year}`;if(keys.has(k))c.validation.errors.push('중복 학교·학과·학년도');keys.add(k);c.validation.ok=!c.validation.errors.length}return{ok:rows.every(x=>x.validation.ok),rows}}catch(e){return{ok:false,error:e.message,rows:[]}}}
async function readWorkbook(file){return XLSX.read(await file.arrayBuffer(),{type:'array'})}
async function previewSchoolFile(input){if(!input.files[0])return;try{const wb=await readWorkbook(input.files[0]);const v=validateSchoolWorkbook(wb);if(v.error)throw new Error(v.error);schoolPreview=v.rows;renderSchoolImport()}catch(e){notify(e.message,'error')}}
function importSchoolCriteria(mode='overwrite'){
  db.criteria=mergeCriteriaSources(safeRead(STORAGE_KEYS.schools,[]),db.criteria);const valid=schoolPreview.filter(x=>x.validation.ok);for(const c of valid){const ix=db.criteria.findIndex(x=>x.schoolName===c.schoolName&&x.department===c.department&&x.year===c.year);c.updatedAt=new Date().toISOString();if(ix<0)db.criteria.push(c);else if(mode==='overwrite'){c.version=Math.max(n(c.version,1),n(db.criteria[ix].version,1)+1);db.criteria[ix]=c}else if(mode==='new'){db.criteria[ix].status='미적용';db.criteria[ix].updatedAt=c.updatedAt;c.version=Math.max(n(c.version,1),n(db.criteria[ix].version,1)+1);db.criteria.push(c)}}markResultsAsStale();saveDb('학교별 일괄등록');notify(`${valid.length}개 기준을 저장했습니다.`);schoolPreview=[];renderSchoolImport()
}
function criteriaWorkbook(includeExamples=false,current=false){
  const list=current?db.criteria:(includeExamples?[exampleCriteria('SCHOOL001','가상미래고등학교','인공지능과'),exampleCriteria('SCHOOL002','가상산업고등학교','기계과'),exampleCriteria('SCHOOL003','가상예술고등학교','디자인과')]:[]);
  const base=list.map(c=>({'기준ID':c.id,'설정버전':c.version||1,'학교명':c.schoolName,'모집학과':c.department,'적용학년도':c.year,'적용상태':c.status,'학교총점':c.schoolTotal,'교과반영만점':c.academicMax,'전체교과가중치':c.academicWeight,'교과산출식':c.academicFormula,'예상합격점수':c.expected,'안정예상점수':c.safe,'도전허용점수차이':c.challengeGap,'소수점처리방식':c.rounding,'자료출처':c.source,'참고메모':c.memo}));
  const sem=list.map(c=>Object.assign({'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department},Object.fromEntries(SEMESTERS.flatMap(x=>[[`${x}_반영`,c.semesters[x].enabled?'Y':'N'],[`${x}_가중치`,c.semesters[x].weight]]))));
  const sub=list.map(c=>Object.assign({'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department},Object.fromEntries(SUBJECTS.flatMap(x=>[[`${x}_반영`,c.subjects[x].enabled?'Y':'N'],[`${x}_가중치`,c.subjects[x].weight]]))));
  const non=list.map(c=>{const r={'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department};NON_ACADEMIC.forEach(k=>{const q=c.nonAcademic[k],px=k==='면접'?'면접':k;r[`${px}_반영`]=q.enabled?'Y':'N';r[`${px}_기본입력만점`]=q.inputMax;r[`${px}_학교반영만점`]=q.schoolMax;r[`${px}_가중치`]=q.weight;r[`${px}_계산방식`]=q.method;r[`${px}_산출식`]=q.formula});return r});
  const guide=[{'항목':'기준ID','설명':'여러 시트에서 같은 학교·학과를 연결합니다.'},{'항목':'반영 여부','설명':'Y 또는 N을 권장합니다.'},{'항목':'주의','설명':'적용 가능 상태만 계산하며 산출식에는 등록 변수와 사칙연산만 사용합니다.'},{'항목':'개인정보','설명':'실제 학생 개인정보를 작성예시에 넣지 마세요.'}];
  const wb=XLSX.utils.book_new();[['학교산출기준',base],['학기설정',sem],['과목설정',sub],['비교과설정',non],['입력안내',guide],['작성예시',includeExamples?base:[]]].forEach(([name,rows])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),name));return wb
}
function exampleCriteria(id,s,d){const c=defaultCriteria();c.id=id;c.schoolName=s;c.department=d;c.status='적용 가능';c.nonAcademic.출석={enabled:true,inputMax:20,schoolMax:15,weight:1,method:'자동 비율 환산',formula:''};c.schoolTotal=85;c.safe=75;c.expected=65;return c}
function exportSchoolCriteriaTemplate(example=false){XLSX.writeFile(criteriaWorkbook(example,false),`고등학교_학교별_일괄등록_${example?'작성예시':'양식'}_2027.xlsx`)}
function exportCurrentSchoolCriteria(){XLSX.writeFile(criteriaWorkbook(false,true),'현재_학교별_등록자료.xlsx');saveDb('학교별 등록자료 다운로드')}

function studentTemplateWorkbook(example=false){const r={'학교':'외동중학교','학년':3,'반':1,'번호':1,'학번':'','이름':'','미인정결석일수':0,'봉사시간':30};SEMESTERS.forEach(s=>SUBJECTS.forEach(x=>r[`${s}_${x}`]=''));const wb=XLSX.utils.book_new(),rows=example?[Object.assign({},r,{학번:'TEST001',이름:'가상학생',...Object.fromEntries(SEMESTERS.flatMap(s=>SUBJECTS.map(x=>[`${s}_${x}`,85])))})]:[r];XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'학생성적');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['입력안내'],['교과는 0~100 원점수 또는 1~5 평점을 입력합니다.'],['미인정 결석이 없으면 0일을 입력합니다.'],['봉사는 실제 시간을 입력하며 30시간 이상은 만점 처리됩니다.'],['인·적성과 면접은 학생 입력 없이 해당 학교만점을 자동 적용합니다.'],['실제 주민등록번호는 입력하지 않습니다.']]),'입력안내');return wb}
function exportStudentTemplate(example=false){XLSX.writeFile(studentTemplateWorkbook(example),`학생_성적_일괄등록_${example?'예시':'양식'}.xlsx`)}
function validateStudentRow(s){const errors=[];if(!s.name)errors.push('이름 누락');if(!s.studentId)errors.push('학번 누락');for(const [key,v] of Object.entries(s.scores)){if(v.raw===''||v.raw==null)continue;if(!Number.isFinite(Number(v.raw))||Number(v.raw)<0||Number(v.raw)>100)errors.push(`${key} 성적 범위 오류`)}if(n(s.nonAcademic?.출석?.raw)<0)errors.push('미인정 결석일수 오류');if(n(s.nonAcademic?.봉사?.raw)<0)errors.push('봉사시간 오류');return{ok:!errors.length,errors,warnings:[]}}
function parseStudentExcel(wb){const rows=workbookRows(wb,'학생성적');if(!rows)throw new Error('학생성적 시트가 없습니다.');return rows.map((r,i)=>{const s={id:uid('STU'),school:String(r['학교']||'외동중학교'),grade:n(r['학년'],3),classNo:String(r['반']||''),number:String(r['번호']||''),studentId:String(r['학번']||'').trim(),name:String(r['이름']||'').trim(),scores:{},nonAcademic:{출석:{raw:n(r['미인정결석일수']),inputMax:0},봉사:{raw:n(r['봉사시간']),inputMax:30},인적성:{raw:0,inputMax:0},면접:{raw:0,inputMax:0}},metricVersion:2,excelRow:i+2};SEMESTERS.forEach(m=>SUBJECTS.forEach(x=>{const raw=r[`${m}_${x}`];const num=n(raw,NaN);s.scores[`${m}_${x}`]={raw,inputType:Number.isFinite(num)&&num<=5?'평점':'원점수',grade:Number.isFinite(num)?(num<=5?num:convertRawScoreToGrade(num)):null,conversionVersion:db.scoreConversion.version}}));s.validation=validateStudentRow(s);return s})}
async function previewStudentFile(input){if(!input.files[0])return;try{studentPreview=parseStudentExcel(await readWorkbook(input.files[0]));renderStudentImport()}catch(e){notify(e.message,'error')}}
async function importStudents(){const ok=studentPreview.filter(x=>x.validation.ok);let errors=0;for(const s of ok){try{const old=db.students.find(x=>x.studentId===s.studentId);if(old){s.id=old.id;updateStudent(s,false)}else saveStudent(s,false)}catch(error){errors++}}saveDb('학생 성적 일괄등록');for(const s of ok){const saved=db.students.find(d=>d.studentId===s.studentId);if(saved)await recalculateResultsForStudent(saved.id,false)}saveDb('학생 저장 후 자동 재계산');refreshAllResultViews();notify(errors?`${ok.length-errors}명 저장, 오류 ${errors}건`:`${ok.length}명 저장 후 자동 재계산 완료`);studentPreview=[];renderStudentImport()}

function calculateSubjectVariables(student,c){let sum=0,count=0,weighted=0,weightSum=0;for(const m of SEMESTERS){if(!c.semesters[m]?.enabled)continue;for(const x of SUBJECTS){if(!c.subjects[x]?.enabled)continue;const g=student.scores[`${m}_${x}`]?.grade;if(!Number.isFinite(Number(g)))continue;const w=n(c.semesters[m].weight,1)*n(c.subjects[x].weight,1);sum+=n(g);count++;weighted+=n(g)*w;weightSum+=w}}return{'평점합':sum,'평점평균':count?sum/count:0,'반영과목수':count,'최고평점합':5*count,'가중평점합':weighted,'가중치합':weightSum,'최고가중평점합':5*weightSum,'교과만점':n(c.academicMax),'전체교과가중치':n(c.academicWeight,1)}}
function applyRounding(v,mode){if(mode==='소수점 유지')return v;if(mode.includes('첫째'))return mode.includes('버림')?Math.floor(v*10)/10:Math.round(v*10)/10;return mode.includes('버림')?Math.floor(v*100)/100:Math.round(v*100)/100}
function calculateAcademicScore(student,c){const vars=calculateSubjectVariables(student,c);if(!vars.반영과목수)throw new Error('학생 필수 교과자료가 없습니다.');const score=c.useAcademicFormula!==false?safelyEvaluateFormula(c.academicFormula,vars):vars.가중평점합/vars.최고가중평점합*n(c.academicMax);if(score>n(c.academicMax)+.001)throw new Error('계산 결과가 반영 만점을 초과했습니다.');return{score:applyRounding(score,c.rounding),vars}}
function calculateNonAcademicScore(student,c){let total=0,details={};for(const k of NON_ACADEMIC){const rule=c.nonAcademic[k];if(!rule?.enabled){details[k]=0;continue}const raw=n(student.nonAcademic?.[k]?.raw),inputMax=n(student.nonAcademic?.[k]?.inputMax||rule.inputMax),isNew=n(student.metricVersion)>=2;let score;if(k==='인적성'||k==='면접')score=n(rule.schoolMax)*n(rule.weight,1);else if(isNew&&k==='출석')score=Math.max(0,n(rule.schoolMax)-raw*n(rule.deductionPerDay,1))*n(rule.weight,1);else if(isNew&&k==='봉사')score=Math.min(raw/Math.max(1,n(rule.fullHours,30)),1)*n(rule.schoolMax)*n(rule.weight,1);else if(rule.method==='학생점수 그대로 사용')score=raw*n(rule.weight,1);else if(rule.method==='산출식 직접 입력')score=safelyEvaluateFormula(rule.formula,{'교과만점':n(rule.schoolMax),'평점합':raw,'평점평균':inputMax});else{if(inputMax<=0)throw new Error(`${k} 입력만점 오류`);score=raw/inputMax*n(rule.schoolMax)*n(rule.weight,1)}if(score>n(rule.schoolMax)*n(rule.weight,1)+.001)throw new Error(`${k} 반영 만점 초과`);details[k]=score;total+=score}return{score:total,details}}
function calculateFinalScore(student,c){const a=calculateAcademicScore(student,c),q=calculateNonAcademicScore(student,c);return{score:applyRounding(a.score*q0()+q.score,c.rounding),academic:a,nonAcademic:q};function q0(){return 1}}
function classifySupportLevel(score,c){if(!Number.isFinite(n(c.expected,NaN)))return'판단 자료 부족';if(score>=n(c.safe))return'안정 지원';if(score>=n(c.expected))return'지원 가능';if(n(c.expected)-score<=n(c.challengeGap))return'도전 지원';return'신중 검토'}
function calculateStudentForSchool(student,c){try{const x=calculateFinalScore(student,c),parts=x.nonAcademic.details||{},gap=x.score-n(c.expected);return{id:`${student.id}|${c.id}`,studentId:student.id,criteriaId:c.id,criteriaVersion:c.version,schoolName:c.schoolName,department:c.department,studentName:student.name,studentNo:student.studentId,academicScore:x.academic.score,attendanceScore:n(parts.출석),volunteerScore:n(parts.봉사),aptitudeScore:n(parts.인적성),interviewScore:n(parts.면접),nonAcademicScore:x.nonAcademic.score,score:x.score,expectedScore:n(c.expected),safeScore:n(c.safe),scoreGap:gap,level:classifySupportLevel(x.score,c),status:'정상',calculatedAt:new Date().toISOString(),studentModifiedAt:student.modifiedAt||'',error:''}}catch(e){return{id:`${student.id}|${c.id}`,studentId:student.id,criteriaId:c.id,criteriaVersion:c.version,schoolName:c.schoolName,department:c.department,studentName:student.name,studentNo:student.studentId,score:'',level:'판단 자료 부족',status:'계산 오류',error:e.message,studentModifiedAt:student.modifiedAt||'',calculatedAt:new Date().toISOString()}}}
async function calculateAllStudentsForAllSchools(){const criteria=db.criteria.filter(x=>['적용','적용 가능'].includes(x.status)),total=db.students.length*criteria.length;if(!total){notify('학생과 적용 학교를 먼저 등록하세요.','error');return}db.results=[];const started=new Date().toISOString(),bar=document.getElementById('calc-progress');let done=0;for(let i=0;i<db.students.length;i+=10){for(const s of db.students.slice(i,i+10))for(const c of criteria){db.results.push(calculateStudentForSchool(s,c));done++}if(bar){bar.classList.remove('hidden');bar.innerHTML=`<div class="font-bold">계산 진행률 ${Math.round(done/total*100)}%</div><div>${db.students.length}명 중 ${Math.min(i+10,db.students.length)}명 계산 · 총 ${total}건 중 ${done}건 완료</div>`}await new Promise(r=>setTimeout(r,0))}db.runs.unshift({started,completed:new Date().toISOString(),total,success:db.results.filter(x=>!x.error).length,errors:db.results.filter(x=>x.error).length});saveDb('전체 자동 계산');notify(`${total}건 계산 완료`);renderCurrentTab()}
function markResultsAsStale(criteriaIds=null,studentIds=null){db.results.forEach(r=>{if((!criteriaIds||criteriaIds.includes(r.criteriaId))&&(!studentIds||studentIds.includes(r.studentId)))r.status='재계산 필요'})}
function markSchoolResultsStale(criteriaId){markResultsAsStale([criteriaId],null)}
function markStudentResultsStale(studentId){markResultsAsStale(null,[studentId])}
function saveCalculationResult(result){const ix=db.results.findIndex(x=>x.studentId===result.studentId&&x.criteriaId===result.criteriaId);if(ix>=0)db.results[ix]=result;else db.results.push(result);return result}
function saveSchoolSetting(setting,recalculate=true){db.criteria=mergeCriteriaSources(safeRead(STORAGE_KEYS.schools,[]),db.criteria);if(db.criteria.some(x=>x.id===setting.id))throw new Error('중복 기준ID입니다.');setting.updatedAt=new Date().toISOString();db.criteria.push(setting);markSchoolResultsStale(setting.id);saveDb('학교 산출기준 신규 저장');return recalculate?recalculateResultsForSchool(setting.id):Promise.resolve([])}
function updateSchoolSetting(setting,recalculate=true){db.criteria=mergeCriteriaSources(safeRead(STORAGE_KEYS.schools,[]),db.criteria);const ix=db.criteria.findIndex(x=>x.id===setting.id);if(ix<0)throw new Error('존재하지 않는 학교 기준입니다.');setting.version=Number(db.criteria[ix].version||1)+1;setting.updatedAt=new Date().toISOString();db.criteria[ix]=setting;markSchoolResultsStale(setting.id);saveDb('학교 산출기준 수정');return recalculate?recalculateResultsForSchool(setting.id):Promise.resolve([])}
function saveStudent(student,recalculate=true){if(db.students.some(x=>x.studentId===student.studentId))throw new Error('학생ID가 중복되었습니다.');student.modifiedAt=new Date().toISOString();db.students.push(student);markStudentResultsStale(student.id);return recalculate?recalculateResultsForStudent(student.id):Promise.resolve([])}
function updateStudent(student,recalculate=true){const ix=db.students.findIndex(x=>x.id===student.id||x.studentId===student.studentId);if(ix<0)throw new Error('존재하지 않는 학생입니다.');student.id=db.students[ix].id;student.modifiedAt=new Date().toISOString();db.students[ix]=student;markStudentResultsStale(student.id);return recalculate?recalculateResultsForStudent(student.id):Promise.resolve([])}
async function recalculateResultsForSchool(criteriaId,persist=true){const c=db.criteria.find(x=>x.id===criteriaId);if(!c)throw new Error('존재하지 않는 학교 기준입니다.');const output=[];for(let i=0;i<db.students.length;i+=10){for(const s of db.students.slice(i,i+10))output.push(saveCalculationResult(calculateStudentForSchool(s,c)));await new Promise(r=>setTimeout(r,0))}if(persist){saveDb(`학교 ${c.schoolName} 자동 재계산`);refreshAllResultViews()}return output}
async function recalculateResultsForStudent(studentId,persist=true){const s=db.students.find(x=>x.id===studentId);if(!s)throw new Error('존재하지 않는 학생입니다.');const output=[];for(const c of db.criteria.filter(x=>['적용','적용 가능'].includes(x.status)))output.push(saveCalculationResult(calculateStudentForSchool(s,c)));if(persist){saveDb(`학생 ${s.studentId} 자동 재계산`);refreshAllResultViews()}return output}
async function recalculateAllResults(){return calculateAllStudentsForAllSchools()}
function refreshAllResultViews(){if(activeAdminTab==='student-results')renderStudentResults();else if(activeAdminTab==='school-results')renderSchoolResults();else if(activeAdminTab==='data')renderData();refreshExportData()}
function refreshExportData(){return db.results}

function sheet(rows){return XLSX.utils.json_to_sheet(rows.length?rows:[{'자료':'없음'}])}
function exportResultsToExcel(){if(!confirm('다운로드 파일에는 학생 개인정보가 포함될 수 있습니다. 학교 보관·공유 규정을 확인하셨습니까?'))return;const wb=XLSX.utils.book_new();const studentSummary=db.students.map(s=>({학번:s.studentId,이름:s.name,학년:s.grade,반:s.classNo,번호:s.number,결과수:db.results.filter(r=>r.studentId===s.id).length}));const detail=db.results.map(r=>({학번:r.studentNo,이름:r.studentName,학교:r.schoolName,학과:r.department,최종점수:r.score,교과점수:r.academicScore,비교과점수:r.nonAcademicScore,지원수준:r.level,상태:r.status,오류:r.error}));const conversions=[];db.students.forEach(s=>Object.entries(s.scores).forEach(([k,v])=>conversions.push({학번:s.studentId,이름:s.name,학기과목:k,원점수:v.raw,변환평점:v.grade,입력방식:v.inputType,변환기준버전:v.conversionVersion})));[['학생별 요약',studentSummary],['학교별 상세결과',detail],['과목별 변환자료',conversions],['오류자료',detail.filter(x=>x.오류)],['학교별 등록',db.criteria],['계산 실행정보',db.runs]].forEach(([nm,rows])=>XLSX.utils.book_append_sheet(wb,sheet(rows),nm));XLSX.writeFile(wb,'외동중학교_고입_전체결과.xlsx');saveDb('전체 결과 다운로드')}

function renderTabs(){document.getElementById('admin-tabs').innerHTML=TABS.map(([id,label])=>`<button onclick="switchAdminTab('${id}')" class="whitespace-nowrap px-3 py-2 rounded-xl text-xs font-bold ${id===activeAdminTab?'bg-blue-600 text-white':'bg-slate-100 text-slate-600'}">${label}</button>`).join('')}
function switchAdminTab(id){activeAdminTab=id;renderTabs();renderCurrentTab()}
function renderCurrentTab(){({criteria:renderCriteria,'school-import':renderSchoolImport,'student-import':renderStudentImport,'student-results':renderStudentResults,'school-results':renderSchoolResults,downloads:renderDownloads,password:renderPasswordChange,data:renderData}[activeAdminTab]||renderCriteria)();prependTabHelp()}
function prependTabHelp(){const panel=document.getElementById('admin-panel'),help=TAB_HELP[activeAdminTab];if(!panel||!help)return;const box=document.createElement('section');box.className='admin-card mb-5 border-l-4 border-blue-500';box.setAttribute('aria-label',`${help[0]} 사용 설명`);box.innerHTML=`<h2 class="font-black text-blue-800">${esc(help[0])} 사용 설명</h2><p class="text-sm mt-2"><strong>용도:</strong> ${esc(help[1])}</p><p class="text-sm mt-1 text-slate-600"><strong>사용 방법:</strong> ${esc(help[2])}</p>`;panel.prepend(box)}
function summaryCards(){return`<div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">${[['학교·학과',db.criteria.length],['학생',db.students.length],['계산 결과',db.results.length],['재계산 필요',db.results.filter(x=>x.status==='재계산 필요').length]].map(([a,b])=>`<div class="admin-card"><p class="text-xs text-slate-500">${a}</p><p class="text-2xl font-black">${b}</p></div>`).join('')}</div>`}
function renderCriteria(){const el=document.getElementById('admin-panel');el.innerHTML=summaryCards()+`<div class="admin-card"><div class="flex justify-between gap-2 mb-4"><div><h2 class="font-black">학교별 산출기준 설정</h2><p class="text-xs text-slate-500">화면 입력과 엑셀 입력은 동일한 데이터 구조를 사용합니다.</p></div><button onclick="openCriteriaEditor()" class="btn-primary">기준 추가</button></div><div class="overflow-auto max-h-[65vh]"><table class="admin-table"><thead><tr><th>기준ID</th><th>학교</th><th>학과</th><th>학년도</th><th>상태</th><th>총점</th><th>예상/안정</th><th>버전</th><th>관리</th></tr></thead><tbody>${db.criteria.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.schoolName)}</td><td>${esc(c.department)}</td><td>${c.year}</td><td>${c.status}</td><td>${c.schoolTotal}</td><td>${c.expected} / ${c.safe}</td><td>v${c.version||1}</td><td><button class="text-blue-600 font-bold" onclick="openCriteriaEditor('${c.id}')">수정</button></td></tr>`).join('')}</tbody></table></div></div>`}
function openCriteriaEditor(id=''){const c=id?db.criteria.find(x=>x.id===id):defaultCriteria();const f=(label,key,type='text')=>`<label class="text-xs font-bold">${label}<input class="admin-input mt-1" name="${key}" type="${type}" value="${esc(c[key])}"></label>`;document.getElementById('edit-modal-body').innerHTML=`<form id="criteria-form" class="space-y-5"><div class="flex justify-between"><h2 class="text-xl font-black">학교 산출기준</h2><button type="button" onclick="closeEditor()">✕</button></div><div class="grid md:grid-cols-4 gap-3">${f('기준ID','id')}${f('학교명','schoolName')}${f('모집학과','department')}${f('적용학년도','year','number')}<label class="text-xs font-bold">적용상태<select class="admin-input mt-1" name="status">${CRITERIA_STATUS.map(x=>`<option ${x===c.status?'selected':''}>${x}</option>`)}</select></label>${f('학교총점','schoolTotal','number')}${f('교과반영만점','academicMax','number')}${f('전체교과가중치','academicWeight','number')}${f('예상합격점수','expected','number')}${f('안정예상점수','safe','number')}${f('도전허용점수차이','challengeGap','number')}<label class="text-xs font-bold">소수점 처리<select class="admin-input mt-1" name="rounding">${ROUNDING.map(x=>`<option ${x===c.rounding?'selected':''}>${x}</option>`)}</select></label></div><label class="text-xs font-bold block">교과 산출식<input class="admin-input mt-1" name="academicFormula" value="${esc(c.academicFormula)}"></label><div><h3 class="font-bold text-sm mb-2">학기 및 가중치</h3><div class="flex gap-4">${SEMESTERS.map(x=>`<label class="text-xs"><input type="checkbox" name="sem_${x}" ${c.semesters[x].enabled?'checked':''}> ${x} <input type="number" step="0.1" class="admin-input w-20 inline" name="semw_${x}" value="${c.semesters[x].weight}"></label>`).join('')}</div></div><div><h3 class="font-bold text-sm mb-2">과목 및 가중치</h3><div class="grid grid-cols-2 md:grid-cols-5 gap-2">${SUBJECTS.map(x=>`<label class="text-xs"><input type="checkbox" name="sub_${x}" ${c.subjects[x].enabled?'checked':''}> ${x}<input type="number" step="0.1" class="admin-input mt-1" name="subw_${x}" value="${c.subjects[x].weight}"></label>`).join('')}</div></div><div><h3 class="font-bold text-sm mb-2">비교과 설정</h3><div class="overflow-auto"><table class="admin-table"><tr><th>영역</th><th>반영</th><th>입력만점</th><th>학교만점</th><th>가중치</th><th>계산방식</th></tr>${NON_ACADEMIC.map(k=>{const q=c.nonAcademic[k];return`<tr><td>${k}</td><td><input type="checkbox" name="non_${k}" ${q.enabled?'checked':''}></td><td><input class="admin-input" name="nonin_${k}" type="number" value="${q.inputMax}"></td><td><input class="admin-input" name="nonmax_${k}" type="number" value="${q.schoolMax}"></td><td><input class="admin-input" name="nonw_${k}" type="number" value="${q.weight}"></td><td><select class="admin-input" name="nonmethod_${k}"><option>학생점수 그대로 사용</option><option ${q.method==='자동 비율 환산'?'selected':''}>자동 비율 환산</option><option>산출식 직접 입력</option></select></td></tr>`}).join('')}</table></div></div><div class="grid md:grid-cols-2 gap-3">${f('자료출처','source')}${f('참고메모','memo')}</div><div id="criteria-errors" class="text-red-600 text-xs"></div><div class="flex gap-2 justify-end"><button type="button" class="btn-secondary" onclick="testCriteriaForm()">계산 시험</button><button type="button" class="btn-secondary" onclick="closeEditor()">취소</button><button class="btn-primary">수정 저장</button></div></form>`;document.getElementById('edit-modal').classList.remove('hidden');document.getElementById('criteria-form').onsubmit=e=>{e.preventDefault();saveCriteriaForm(c)}}
function formCriteria(old){const fd=new FormData(document.getElementById('criteria-form')),c=structuredClone(old);['schoolName','department','status','academicFormula','rounding','source','memo'].forEach(k=>c[k]=fd.get(k));c.id=old.id;['year','schoolTotal','academicMax','academicWeight','expected','safe','challengeGap'].forEach(k=>c[k]=n(fd.get(k)));SEMESTERS.forEach(x=>c.semesters[x]={enabled:fd.has(`sem_${x}`),weight:n(fd.get(`semw_${x}`),1)});SUBJECTS.forEach(x=>c.subjects[x]={enabled:fd.has(`sub_${x}`),weight:n(fd.get(`subw_${x}`),1)});NON_ACADEMIC.forEach(k=>c.nonAcademic[k]={enabled:fd.has(`non_${k}`),inputMax:n(fd.get(`nonin_${k}`)),schoolMax:n(fd.get(`nonmax_${k}`)),weight:n(fd.get(`nonw_${k}`),1),method:fd.get(`nonmethod_${k}`),formula:''});return c}
function testCriteriaForm(){const c=formCriteria(defaultCriteria()),v=validateSchoolCriteriaRow(c),el=document.getElementById('criteria-errors');el.textContent=[...v.errors,...v.warnings].join(' / ')||'검증 성공'}
async function saveCriteriaForm(old){const c=formCriteria(old),v=validateSchoolCriteriaRow(c);if(!v.ok){document.getElementById('criteria-errors').textContent=v.errors.join(' / ');return}if(v.warnings.length&&!confirm(v.warnings.join(' / ')+' 그래도 저장하시겠습니까?')){document.getElementById('criteria-errors').textContent=v.warnings.join(' / ');return}try{const exists=db.criteria.some(x=>x.id===old.id);if(exists)await updateSchoolSetting(c,true);else await saveSchoolSetting(c,true);closeEditor();renderCurrentTab();notify(`학교 산출기준이 저장되었습니다. 해당 학교 학생 ${db.students.length}명의 결과를 다시 계산했습니다.`)}catch(error){document.getElementById('criteria-errors').textContent=error.message;notify(error.message,'error')}}
function closeEditor(){document.getElementById('edit-modal').classList.add('hidden')}
function previewStats(rows){return{all:rows.length,ok:rows.filter(x=>x.validation.ok).length,warn:rows.filter(x=>x.validation.warnings?.length).length,error:rows.filter(x=>!x.validation.ok).length}}
function renderSchoolImport(){const s=previewStats(schoolPreview),el=document.getElementById('admin-panel');el.innerHTML=`<div class="admin-card space-y-4"><h2 class="font-black">학교 산출기준 일괄등록</h2><div class="flex flex-wrap gap-2"><button class="btn-secondary" onclick="exportSchoolCriteriaTemplate(false)">엑셀 양식 다운로드</button><button class="btn-secondary" onclick="exportSchoolCriteriaTemplate(true)">작성 예시 포함</button><button class="btn-secondary" onclick="exportCurrentSchoolCriteria()">현재 기준 내보내기</button></div><input type="file" accept=".xlsx,.xls" onchange="previewSchoolFile(this)" class="admin-input"><div class="grid grid-cols-4 gap-2 text-center">${[['전체',s.all],['정상',s.ok],['경고',s.warn],['오류',s.error]].map(([a,b])=>`<div class="bg-slate-50 p-3 rounded-xl"><b>${b}</b><br><span class="text-xs">${a}</span></div>`).join('')}</div><div class="overflow-auto max-h-[50vh]"><table class="admin-table"><tr><th>행</th><th>기준ID</th><th>학교</th><th>학과</th><th>상태</th><th>검증</th><th>내용</th></tr>${schoolPreview.map(c=>`<tr><td>${c.excelRow}</td><td>${esc(c.id)}</td><td>${esc(c.schoolName)}</td><td>${esc(c.department)}</td><td>${c.status}</td><td>${c.validation.ok?'정상':'오류'}</td><td class="text-red-600">${esc([...c.validation.errors,...c.validation.warnings].join(', '))}</td></tr>`).join('')}</table></div>${schoolPreview.length?`<div class="flex flex-wrap gap-2"><button class="btn-primary" onclick="importSchoolCriteria('overwrite')">정상자료 저장·덮어쓰기</button><button class="btn-secondary" onclick="importSchoolCriteria('new')">새 버전으로 저장</button><button class="btn-secondary" onclick="calculateAllStudentsForAllSchools()">저장 후 전체 결과 다시 계산</button></div>`:''}<div id="calc-progress" class="hidden bg-blue-50 text-blue-700 p-3 rounded-xl text-xs"></div></div>`}
function renderStudentImport(){const s=previewStats(studentPreview),el=document.getElementById('admin-panel');el.innerHTML=`<div class="admin-card space-y-4"><h2 class="font-black">학생 성적 일괄등록</h2><div class="flex gap-2"><button class="btn-secondary" onclick="exportStudentTemplate(false)">학생 엑셀 양식</button><button class="btn-secondary" onclick="exportStudentTemplate(true)">가상 예시 포함</button></div><input type="file" accept=".xlsx,.xls" onchange="previewStudentFile(this)" class="admin-input"><div>전체 ${s.all}명 · 정상 ${s.ok}명 · 오류 ${s.error}명</div><div class="overflow-auto max-h-[50vh]"><table class="admin-table"><tr><th>행</th><th>학번</th><th>이름</th><th>학년/반/번호</th><th>상태</th><th>오류</th></tr>${studentPreview.map(x=>`<tr><td>${x.excelRow}</td><td>${esc(x.studentId)}</td><td>${esc(x.name)}</td><td>${x.grade}/${esc(x.classNo)}/${esc(x.number)}</td><td>${x.validation.ok?'정상':'오류'}</td><td class="text-red-600">${esc(x.validation.errors.join(', '))}</td></tr>`).join('')}</table></div>${studentPreview.length?`<div class="flex gap-2"><button class="btn-primary" onclick="importStudents()">정상자료 저장</button><button class="btn-secondary" onclick="calculateAllStudentsForAllSchools()">전체 학교 자동 계산</button></div>`:''}<div id="calc-progress" class="hidden bg-blue-50 text-blue-700 p-3 rounded-xl text-xs"></div></div>`}
function renderStudentResults(){const q=(document.getElementById('student-search')?.value||'').toLowerCase(),rows=db.results.filter(r=>!q||`${r.studentName}${r.studentNo}`.toLowerCase().includes(q));document.getElementById('admin-panel').innerHTML=summaryCards()+`<div class="admin-card"><div class="flex justify-between gap-2 mb-3"><input id="student-search" oninput="renderStudentResults()" value="${esc(q)}" class="admin-input max-w-sm" placeholder="학생 이름 또는 학번"><button class="btn-primary" onclick="calculateAllStudentsForAllSchools()">전체 재계산</button></div><div id="calc-progress" class="hidden bg-blue-50 p-3 rounded-xl mb-3 text-xs"></div><div class="overflow-auto max-h-[60vh]"><table class="admin-table"><tr><th>학번</th><th>이름</th><th>학교</th><th>학과</th><th>점수</th><th>지원수준</th><th>상태</th><th>오류</th></tr>${rows.map(r=>`<tr><td>${esc(r.studentNo)}</td><td>${esc(r.studentName)}</td><td>${esc(r.schoolName)}</td><td>${esc(r.department)}</td><td>${r.score}</td><td>${r.level}</td><td>${r.status}</td><td>${esc(r.error)}</td></tr>`).join('')}</table></div><p class="text-xs text-slate-500 mt-3">본 결과는 교사가 입력한 산출기준과 예상 합격점수를 사용한 참고자료이며 실제 합격을 보장하지 않습니다.</p></div>`}
function renderSchoolResults(){const schools=[...new Set(db.results.map(r=>r.schoolName))],selected=document.getElementById('school-filter')?.value||schools[0]||'',rows=db.results.filter(r=>r.schoolName===selected).sort((a,b)=>n(b.score)-n(a.score));document.getElementById('admin-panel').innerHTML=`<div class="admin-card"><div class="flex justify-between gap-2 mb-3"><select id="school-filter" onchange="renderSchoolResults()" class="admin-input max-w-sm">${schools.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`)}</select><button class="btn-primary" onclick="calculateAllStudentsForAllSchools()">변경 학교 모두 재계산</button></div><div id="calc-progress" class="hidden"></div><div class="overflow-auto"><table class="admin-table"><tr><th>순위</th><th>학번</th><th>이름</th><th>학과</th><th>점수</th><th>지원수준</th><th>상태</th></tr>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.studentNo)}</td><td>${esc(r.studentName)}</td><td>${esc(r.department)}</td><td>${r.score}</td><td>${r.level}</td><td>${r.status}</td></tr>`).join('')}</table></div></div>`}
function renderDownloads(){document.getElementById('admin-panel').innerHTML=`<div class="grid md:grid-cols-2 gap-4"><div class="admin-card space-y-3"><h2 class="font-black">전체 결과 다운로드</h2><p class="text-xs text-slate-500">학생별 요약, 학교별 상세결과, 과목별 변환자료, 오류자료, 학교 산출기준, 계산 실행정보를 포함합니다.</p><button class="btn-primary" onclick="exportResultsToExcel()">전체 결과 엑셀 다운로드</button></div><div class="admin-card space-y-3"><h2 class="font-black">학교 기준 내보내기</h2><p class="text-xs text-slate-500">내보낸 파일은 수정 후 다시 등록할 수 있습니다.</p><button class="btn-secondary" onclick="exportCurrentSchoolCriteria()">현재 기준 엑셀 다운로드</button></div></div>`}
function renderData(){document.getElementById('admin-panel').innerHTML=summaryCards()+`<div class="grid md:grid-cols-2 gap-4"><div class="admin-card space-y-3"><h2 class="font-black">교사용 비밀번호</h2><p class="text-sm font-black text-blue-700 bg-blue-50 p-3 rounded">모든 교사용 화면의 비밀번호는 6673으로 통일되어 있습니다.</p><p class="text-xs text-amber-700 bg-amber-50 p-2 rounded">이 프로젝트는 서버 없는 정적 앱입니다. 비밀번호는 같은 브라우저의 일반 사용자 구분용이며 실제 계정 보안을 대신하지 않습니다.</p></div><div class="admin-card space-y-3"><h2 class="font-black">데이터 삭제</h2><button class="btn-danger" onclick="deleteStudents()">학생 자료 전체 삭제</button><button class="btn-danger" onclick="deleteExpired()">1년 지난 감사기록 삭제</button><button class="btn-danger" onclick="resetAllData()">모든 교사 데이터 초기화</button></div><div class="admin-card md:col-span-2"><h2 class="font-black mb-3">최근 기록</h2><div class="max-h-60 overflow-auto text-xs">${db.audit.slice(0,100).map(x=>`<div class="border-b py-2">${new Date(x.at).toLocaleString()} · ${esc(x.action)}</div>`).join('')}</div></div></div>`}
function deleteStudents(){if(confirm('학생 자료와 계산 결과를 모두 삭제합니까?')){db.students=[];db.results=[];saveDb('학생 자료 전체 삭제');renderData()}}
function deleteExpired(){const cut=Date.now()-365*86400000;db.audit=db.audit.filter(x=>new Date(x.at).getTime()>=cut);saveDb('보관기간 경과 기록 삭제');renderData()}
function resetAllData(){if(confirm('학교 기준, 학생, 결과를 모두 삭제합니까?')){db=freshDb();saveDb('전체 초기화',false);renderData()}}
function downloadFullBackup(){
  const storage={};FULL_BACKUP_KEYS.forEach(key=>{const raw=localStorage.getItem(key);if(raw!==null)storage[key]=raw});
  const payload={format:'oeadong-localstorage-backup',version:1,exportedAt:new Date().toISOString(),origin:location.origin,storage};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a'),date=new Date().toISOString().slice(0,10);
  a.href=url;a.download=`외동중_고입예측_전체백업_${date}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);notify(`${Object.keys(storage).length}개 저장항목을 백업했습니다.`)
}
function chooseFullBackup(){const input=document.getElementById('full-backup-file');if(input){input.value='';input.click()}}
async function restoreFullBackup(input){
  const file=input.files?.[0];if(!file)return;
  try{
    const payload=JSON.parse(await file.text());if(payload?.format!=='oeadong-localstorage-backup'||payload?.version!==1||!payload.storage||typeof payload.storage!=='object')throw new Error('이 앱에서 만든 전체 백업 JSON 파일이 아닙니다.');
    const entries=Object.entries(payload.storage).filter(([key,value])=>FULL_BACKUP_KEYS.includes(key)&&typeof value==='string');if(!entries.length)throw new Error('복원할 저장자료가 없습니다.');
    entries.forEach(([key,value])=>{JSON.parse(value)});
    if(!confirm(`백업자료 ${entries.length}개 항목을 현재 브라우저에 복원합니다.\n파일에 없는 현재 자료는 삭제하지 않습니다. 계속할까요?`))return;
    const before=Object.fromEntries(entries.map(([key])=>[key,localStorage.getItem(key)]));
    try{entries.forEach(([key,value])=>localStorage.setItem(key,value));for(const [key,value] of entries)if(localStorage.getItem(key)!==value)throw new Error(`${key} 복원 확인 실패`)}catch(error){Object.entries(before).forEach(([key,value])=>value===null?localStorage.removeItem(key):localStorage.setItem(key,value));throw error}
    alert('전체 백업 복원이 완료되었습니다. 화면을 새로 불러옵니다.');location.reload()
  }catch(error){notify(`백업 복원 실패: ${error.message}`,'error')}
}
