function deleteSchoolSetting(id){
  const target=db.criteria.find(x=>x.id===id);if(!target){notify('삭제할 학교자료를 찾을 수 없습니다.','error');return}
  const resultCount=db.results.filter(x=>x.criteriaId===id).length,question=`${target.schoolName} / ${target.department} / ${target.year} 등록자료를 삭제합니까?\n\n연결된 예측결과 ${resultCount}건도 함께 삭제됩니다. 다른 학교와 학생 원본자료는 유지됩니다.`;
  if(!confirm(question))return;
  try{
    localStorage.setItem(SCHOOL_DELETION_BACKUP_KEY,JSON.stringify({deletedAt:new Date().toISOString(),target,criteria:db.criteria,results:db.results}));
    db.criteria=db.criteria.filter(x=>x.id!==id);db.results=db.results.filter(x=>x.criteriaId!==id);
    const sameSchoolRemains=db.criteria.some(x=>String(x.schoolName).trim()===String(target.schoolName).trim());
    if(!sameSchoolRemains){const legacy=safeRead('odong-admission-project-v1',[]);if(Array.isArray(legacy))localStorage.setItem('odong-admission-project-v1',JSON.stringify(legacy.filter(x=>String(x?.name||'').trim()!==String(target.schoolName).trim())))}
    saveDb(`학교 등록자료 삭제: ${target.schoolName} / ${target.department}`,false);localStorage.setItem(SCHOOL_BACKUP_KEY,JSON.stringify(db.criteria));closeEditor();renderCurrentTab();notify(`${target.schoolName} 등록자료를 삭제했습니다. 삭제 직전 자료는 복구용 저장소에 보관했습니다.`)
  }catch(error){console.error(error);notify(`학교 삭제 실패: ${error.message}`,'error')}
}
