criteriaWorkbook=function(includeExamples=false,current=false){
  const list=current?db.criteria:(includeExamples?[exampleCriteria('SCHOOL001','가상고등학교','전체학과')]:[]);
  const base=list.map(c=>({'기준ID':c.id,'설정버전':c.version||1,'학교명':c.schoolName,'모집학과':c.department,'적용학년도':c.year,'적용상태':['적용','적용 가능'].includes(c.status)?'적용':'미적용','학교총점':c.schoolTotal,'교과반영만점':c.academicMax,'교과산출식사용':c.useAcademicFormula!==false?'Y':'N','교과산출식':c.academicFormula,'예상합격점수':c.expected,'안정예상점수':c.safe,'도전허용점수차이':c.challengeGap,'소수점처리방식':c.rounding,'참고메모':c.memo}));
  const sem=list.map(c=>Object.assign({'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department},Object.fromEntries(SEMESTERS.flatMap(x=>[[`${x}_반영`,c.semesters[x].enabled?'Y':'N'],[`${x}_가중치`,c.semesters[x].weight]]))));
  const sub=list.map(c=>Object.assign({'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department},Object.fromEntries(SUBJECTS.flatMap(x=>[[`${x}_반영`,c.subjects[x].enabled?'Y':'N'],[`${x}_가중치`,c.subjects[x].weight]]))));
  const non=list.map(c=>{const a=c.nonAcademic.출석||{},v=c.nonAcademic.봉사||{},p=c.nonAcademic.인적성||{},m=c.nonAcademic.면접||{};return{'기준ID':c.id,'학교명':c.schoolName,'모집학과':c.department,'출석_반영':a.enabled?'Y':'N','출석_학교만점':a.schoolMax,'출석_결석1일당감점':n(a.deductionPerDay,1),'출석_가중치':n(a.weight,1),'봉사_반영':v.enabled?'Y':'N','봉사_학교만점':v.schoolMax,'봉사_만점인정시간':n(v.fullHours,30),'봉사_가중치':n(v.weight,1),'인적성_반영':p.enabled?'Y':'N','인적성_학교만점':p.schoolMax,'인적성_가중치':n(p.weight,1),'면접_반영':m.enabled?'Y':'N','면접_학교만점':m.schoolMax,'면접_가중치':n(m.weight,1)}});
  const guide=[{'항목':'학생 출석','설명':'미인정 결석일수를 입력하며 0일이면 학교 출석만점을 적용합니다.'},{'항목':'학생 봉사','설명':'봉사시간을 입력하며 기본 30시간 이상이면 학교 봉사만점을 적용합니다.'},{'항목':'인적성·면접','설명':'학생 입력 없이 반영 학교의 학교만점을 자동 적용합니다.'}];
  const wb=XLSX.utils.book_new();[['학교별 등록',base],['학기설정',sem],['과목설정',sub],['비교과설정',non],['입력안내',guide]].forEach(([name,rows])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),name));return wb
}
parseSchoolCriteriaExcel=function(wb){
  const base=workbookRows(wb,'학교별 등록')||workbookRows(wb,'학교산출기준');if(!base)throw new Error('필수 시트 누락: 학교별 등록');const sem=workbookRows(wb,'학기설정')||[],sub=workbookRows(wb,'과목설정')||[],non=workbookRows(wb,'비교과설정')||[];
  return base.map((r,i)=>{const c=defaultCriteria();Object.assign(c,{id:String(r['기준ID']||c.id).trim(),schoolName:String(r['학교명']||'').trim(),department:String(r['모집학과']||'').trim(),year:n(r['적용학년도'],2027),status:['적용','적용 가능'].includes(String(r['적용상태']))?'적용':'미적용',schoolTotal:n(r['학교총점']),academicMax:n(r['교과반영만점']),useAcademicFormula:bool(r['교과산출식사용']??'Y'),academicFormula:String(r['교과산출식']||c.academicFormula),expected:n(r['예상합격점수']),safe:n(r['안정예상점수']),challengeGap:n(r['도전허용점수차이']),rounding:String(r['소수점처리방식']||c.rounding),memo:String(r['참고메모']||''),excelRow:i+2});const sr=sem.find(x=>String(x['기준ID'])===c.id)||{},ur=sub.find(x=>String(x['기준ID'])===c.id)||{},nr=non.find(x=>String(x['기준ID'])===c.id)||{};SEMESTERS.forEach(x=>c.semesters[x]={enabled:bool(sr[`${x}_반영`]??'N'),weight:n(sr[`${x}_가중치`],1)});SUBJECTS.forEach(x=>c.subjects[x]={enabled:bool(ur[`${x}_반영`]??'N'),weight:n(ur[`${x}_가중치`],1)});NON_ACADEMIC.forEach(k=>{const old=c.nonAcademic[k];c.nonAcademic[k]={...old,enabled:bool(nr[`${k}_반영`]??'N'),schoolMax:n(nr[`${k}_학교만점`]??nr[`${k}_학교반영만점`]),weight:n(nr[`${k}_가중치`],1),inputMax:n(old.inputMax,20),deductionPerDay:k==='출석'?n(nr['출석_결석1일당감점'],1):1,fullHours:k==='봉사'?n(nr['봉사_만점인정시간'],30):30}});c.validation=validateSchoolCriteriaRow(c);return c})
}
db.criteria=db.criteria.map(c=>({...c,status:['적용','적용 가능'].includes(c.status)?'적용':'미적용',useAcademicFormula:c.useAcademicFormula??true,nonAcademic:Object.fromEntries(NON_ACADEMIC.map(k=>[k,{inputMax:20,schoolMax:0,weight:1,method:'자동 비율 환산',formula:'',deductionPerDay:1,fullHours:30,...(c.nonAcademic?.[k]||{})}]))}));

